<script>
const roll=document.getElementById('roll'), meters=document.getElementById('meters'), discount=document.getElementById('discount');
function calc(){const o=roll.options[roll.selectedIndex],p=Number(o?.dataset?.price||0),max=Number(o?.dataset?.meters||0),m=Number(meters.value||0),d=Math.min(100,Math.max(0,Number(discount.value||0)));document.getElementById('total').textContent='Bs '+(Math.max(0,m*p*(1-d/100)).toFixed(2));document.getElementById('availability').textContent=o?.value?`Disponible: ${max} m · Precio: Bs ${p}/m`:'Selecciona un rollo para ver su disponibilidad.';meters.max=max||'';}[roll,meters,discount].forEach(e=>e.addEventListener('input',calc));calc();
</script>
